components.plan:
{
  "steps": [
    {
      "type": "tool",
      "name": "quote",
      "output_key": "quote",
      "tool": "market_quote",
      "args": {
        "ticker": "{{question}}"
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "path",
      "output_key": "path",
      "tool": "candlesticks",
      "args": {
        "ticker": "{{question}}",
        "hours_back": 0.75,
        "hourly": false
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "tape",
      "output_key": "tape",
      "tool": "previous_trades",
      "args": {
        "ticker": "{{question}}",
        "limit": 12
      },
      "fail_ok": true
    },
    {
      "type": "prompt",
      "name": "predict",
      "output_key": "prediction",
      "prompt": "Contract: {{question}}\nBook now: {{quote}}\nGame: {{game}}\nMinute bars, last 45m: {{path}}\nRecent prints: {{tape}}\n\nHow many cents does this mid move over the next 5 minutes, and how wide a market would you make around that? Zero cents is a real answer on a quiet book. Quote a width you would actually stand behind on both sides.",
      "tools": [],
      "max_tool_iterations": 6,
      "output_schema": {
        "type": "object",
        "properties": {
          "delta_cents": {
            "type": "number",
            "description": "How many cents the mid will MOVE over the next five minutes. Negative for down, 0 for no move. Do not state a price \u2014 state the change."
          },
          "half_width_cents": {
            "type": "number",
            "description": "Half the width of the tightest two-sided market you would actually stand behind, in cents. This is your quote: you are saying you would buy at (prediction - this) and sell at (prediction + this). Narrow means you will trade; wide means you will not."
          },
          "confidence": {
            "type": "number",
            "description": "0-1. How sure, given how thin and noisy this book is."
          },
          "driver": {
            "type": "string",
            "description": "The one thing you expect to move it, or why nothing will."
          },
          "falsifier": {
            "type": "string",
            "description": "What would show this call was wrong, before settlement."
          }
        },
        "required": [
          "delta_cents",
          "half_width_cents",
          "confidence",
          "driver",
          "falsifier"
        ],
        "additionalProperties": false
      }
    }
  ]
}

